#!/usr/bin/env bash
# Generates ./.env with fresh random secrets. Refuses to overwrite an existing
# file so a running lab never loses its munge key or DB passwords.
set -euo pipefail
ROOT=$(cd "$(dirname "$0")/.." && pwd)
source "$ROOT/scripts/lib/log.sh"

ENV_FILE="$ROOT/.env"
if [[ -f $ENV_FILE ]]; then
  log info init-env ".env already exists; leaving it untouched"
  exit 0
fi

rand() { head -c "$1" /dev/urandom | base64 | tr -dc 'A-Za-z0-9' | head -c "$2"; }

umask 077
cat > "$ENV_FILE" <<ENV
# Local lab secrets. Generated by scripts/init-env.sh. Never commit this file.
MUNGE_KEY_B64=$(head -c 1024 /dev/urandom | base64 -w0)
MYSQL_ROOT_PASSWORD=$(rand 64 32)
SLURMDBD_DB_PASSWORD=$(rand 64 32)
GRAFANA_ADMIN_PASSWORD=$(rand 64 20)
# Comma-separated user:token pairs. The token alone determines which POSIX user a job runs as.
PORTAL_API_TOKENS=alice:$(rand 64 32),bob:$(rand 64 32)
# Set to a public Git URL (e.g. https://github.com/<you>/<repo>.git) to deploy workloads via ArgoCD.
GITOPS_REPO_URL=
GITOPS_REVISION=main
ENV
log info init-env "wrote $ENV_FILE"
